		/** 
		 * Tests creating a new Branch.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Branch");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Branch" );

			try {            
				Branch entity = BranchService.getBranchInstance().createBranch( generateNewEntity() );
				thePrimaryKey = entity.getBranchId();
				LOGGER.info( "-- Successfully created a Branch with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Branch. 
		 */
		public Branch testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Branch" );

			Branch entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Branch with primary key" );
			msg.append( thePrimaryKey );
			
			BranchFetchOneSummary fetchOneSummary = new BranchFetchOneSummary( thePrimaryKey );

			try {
				entity = BranchService.getBranchInstance().getBranch( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Branch " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Branch.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Branch." );

			StringBuilder msg = new StringBuilder( "Failed to update a Branch : " );        
			Branch entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Branch." );

				// for use later on...
				thePrimaryKey = entity.getBranchId();

				BranchService proxy = BranchService.getBranchInstance();            
				proxy.updateBranch( entity );   

				LOGGER.info( "-- Successfully saved Branch - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Branch.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Branch." );

			try{
			    Branch entity = testRead(); 
				BranchService.getBranchInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Branch with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Branch with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Branchs.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Branchs:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Branch : " );        
			List<Branch> collection  = null;

			try {
				// call the static get method on the BranchService
				collection = BranchService.getBranchInstance().getAllBranch();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Branch entity = null;            
					Iterator<Branch> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBranchId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

